
ALTER TABLE public.custom_value_sets
  ADD COLUMN IF NOT EXISTS oid TEXT,
  ADD COLUMN IF NOT EXISTS vocabulary TEXT,
  ADD COLUMN IF NOT EXISTS type TEXT NOT NULL DEFAULT 'extensional',
  ADD COLUMN IF NOT EXISTS intensional_rule JSONB,
  ADD COLUMN IF NOT EXISTS clinical_application TEXT,
  ADD COLUMN IF NOT EXISTS fhir_url TEXT,
  ADD COLUMN IF NOT EXISTS steward TEXT DEFAULT 'S.P.E.H.R. Terminology Services',
  ADD COLUMN IF NOT EXISTS peer_reviewer TEXT,
  ADD COLUMN IF NOT EXISTS version TEXT DEFAULT '1.0.0',
  ADD COLUMN IF NOT EXISTS change_history JSONB DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS binding_strength TEXT DEFAULT 'preferred';

UPDATE public.custom_value_sets SET vocabulary = system WHERE vocabulary IS NULL;

-- Dedupe before adding unique constraint
DELETE FROM public.custom_value_sets a USING public.custom_value_sets b
WHERE a.ctid < b.ctid AND a.name = b.name;

CREATE UNIQUE INDEX IF NOT EXISTS custom_value_sets_name_key ON public.custom_value_sets (name);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.custom_value_sets TO authenticated;
GRANT SELECT ON public.custom_value_sets TO anon;
GRANT ALL ON public.custom_value_sets TO service_role;

